  "implementation": "def solve(case):
    payload = case.get('payload')
    if payload is None:
        raise ValueError('Missing payload')
    nodes = payload.get('nodes')
    threshold = payload.get('utility_threshold')
    if not isinstance(nodes, list) or not isinstance(threshold, (int, float)):
        raise ValueError('Invalid payload fields')
    id_to_node = {}
    children = {}
    for node in nodes:
        if not all(k in node for k in ('id','parent','removable','utility','depth')):
            raise ValueError('Missing required node field')
        nid = node['id']
        id_to_node[nid] = node
        parent = node['parent']
        if parent is not None:
            children.setdefault(parent, []).append(nid)
    # initial queue: descending depth, then stable node-id order
    queue = [n['id'] for n in sorted(nodes, key=lambda n: (-n['depth'], n['id']))]
    removed = set()
    visit_order = []
    # mutable children list (we will remove child entries)
    cur_children = {k: list(v) for k, v in children.items()}
    while queue:
        nid = queue.pop(0)
        visit_order.append(nid)
        if nid in removed:
            continue
        node = id_to_node[nid]
        is_leaf = len(cur_children.get(nid, [])) == 0
        if is_leaf and node['removable'] and node['utility'] <= threshold:
            removed.add(nid)
            parent = node['parent']
            if parent is not None and parent not in removed:
                # remove nid from parent's children list
                if parent in cur_children and nid in cur_children[parent]:
                    cur_children[parent].remove(nid)
                queue.append(parent)
    retained_ids = [n['id'] for n in nodes if n['id'] not in removed]
    return {'retained_ids': retained_ids, 'visit_order': visit_order}"
}
